(function(root){const scenarios=[{"id":"01","title":"Pesanan masuk dari QR kamar","operator":["Periksa nama, kamar, paket, dan permintaan pelanggan.","Terima pesanan, lalu ikuti checklist sampai barang diserahkan dan dana cocok."],"owner":["Pantau pesanan yang belum diterima; pastikan pembayaran dan setoran diperiksa."],"evidence":["Pesanan awal, petugas penerima, serta bukti barang dan pembayaran."],"closure":"Satu pesanan tersimpan. Penyelesaian mengikuti seluruh langkah barang dan dana."},{"id":"02","title":"Tombol kirim tertekan dua kali","operator":["Periksa nomor pesanan yang muncul.","Gunakan pesanan yang sama; buat pesanan baru hanya untuk cucian lain."],"owner":["Jika terlihat dua pesanan untuk cucian yang sama, periksa riwayat dan catat koreksinya."],"evidence":["Nomor pesanan dan waktu pengiriman."],"closure":"Dua klik yang sama mengembalikan satu pesanan, tanpa tagihan tambahan."},{"id":"03","title":"QR kamar tidak valid","operator":["Hentikan pengisian jika QR ditolak atau kamar yang tampil tidak sesuai.","Laporkan kepada Owner dan gunakan QR kamar yang benar."],"owner":["Periksa daftar kamar dan buat QR pengganti bila diperlukan."],"evidence":["Kamar yang benar, hasil pemeriksaan QR, dan catatan penggantian."],"closure":"Pesanan tidak dibuat dari QR yang salah. Pelanggan dapat melanjutkan dari QR yang sah."},{"id":"04","title":"Dua petugas menerima pesanan bersamaan","operator":["Periksa siapa yang tercatat menerima pesanan.","Koordinasikan pekerjaan; penerimaan pertama tetap tersimpan."],"owner":["Alihkan penugasan dengan alasan jika petugas perlu diganti."],"evidence":["Nama penerima pertama, waktu penerimaan, dan riwayat penugasan."],"closure":"Hanya satu penerima pertama; pergantian petugas dapat ditelusuri."},{"id":"05","title":"Pelanggan memperbarui pesanan","operator":["Bandingkan pesanan awal dengan perubahan terbaru.","Terima perubahan terbaru sebelum melanjutkan pekerjaan yang terdampak."],"owner":["Tindak lanjuti pesanan yang perubahannya belum dibaca petugas."],"evidence":["Rincian sebelum dan sesudah perubahan, petugas, dan waktu persetujuan."],"closure":"Versi yang diterima petugas sama dengan pesanan terbaru."},{"id":"06","title":"Batal sebelum diterima petugas","operator":["Periksa bahwa barang dan uang belum diterima.","Catat permintaan serta alasan pembatalan."],"owner":["Periksa bila ada barang, uang, atau kendala yang masih tercatat."],"evidence":["Alasan pembatalan dan posisi barang maupun pembayaran."],"closure":"Pesanan batal tanpa kewajiban barang, uang, atau kendala tersisa."},{"id":"07","title":"Batal setelah barang dijemput","operator":["Hentikan pekerjaan yang belum dimulai.","Kembalikan barang kepada penerima yang benar dan simpan buktinya."],"owner":["Putuskan pembatalan bila pekerjaan sudah berjalan; periksa kewajiban pengembalian dana."],"evidence":["Bukti penjemputan, alasan pembatalan, penerima, dan bukti pengembalian."],"closure":"Barang sudah kembali dan kewajiban pembayaran maupun kendala sudah diselesaikan."},{"id":"08","title":"Pelanggan datang tanpa mengisi pesanan","operator":["Pilih Tambah pesanan dibantu petugas dan kamar yang aktif.","Segera foto barang, isi kantong dan lokasi, lalu pasang label."],"owner":["Periksa identitas pelanggan sebelum pembayaran atau proses dimulai."],"evidence":["Data kamar, identitas, petugas pembuat, dan bukti penerimaan barang."],"closure":"Pesanan tercatat dan identitas dikonfirmasi; lanjutkan checklist biasa."},{"id":"09","title":"Pelanggan pergi sebelum data lengkap","operator":["Simpan data yang sudah diketahui dan amankan barang dengan label.","Minta pelanggan melengkapi nama atau nomor kontak melalui tautan pesanan."],"owner":["Periksa identitas dengan bukti bila pelanggan belum merespons."],"evidence":["Kamar, foto barang, upaya menghubungi pelanggan, dan bukti identitas."],"closure":"Identitas sudah dipastikan sebelum pembayaran atau pekerjaan dimulai."},{"id":"10","title":"Pemilik dan kamar belum diketahui","operator":["Catat sebagai barang belum dikenal.","Foto, beri label, dan simpan terpisah agar tidak tercampur."],"owner":["Pastikan pemilik dan kamar aktif dengan bukti, lalu tautkan ke pesanan pelanggan."],"evidence":["Foto barang, kantong, lokasi, serta bukti pemilik dan kamar."],"closure":"Catatan awal tetap tersimpan; pekerjaan dilanjutkan pada pesanan pelanggan yang sudah ditautkan."},{"id":"11","title":"Pelanggan mengonfirmasi pesanan bantuan","operator":["Berikan tautan hanya kepada pemilik pesanan.","Periksa apakah identitas sudah dikonfirmasi sebelum melanjutkan."],"owner":["Bantu verifikasi dengan bukti jika pelanggan tidak dapat memakai tautan."],"evidence":["Konfirmasi pelanggan atau bukti pemeriksaan Owner."],"closure":"Identitas terkonfirmasi dan pekerjaan kembali ke langkah yang sesuai."},{"id":"12","title":"Pelanggan menyatakan barang bukan miliknya","operator":["Hentikan proses dan simpan barang terpisah.","Catat kendala serta periksa label dan asal barang."],"owner":["Pastikan pemilik yang benar dengan bukti sebelum melanjutkan atau mengembalikan barang."],"evidence":["Pernyataan pelanggan, foto label, serta hasil penelusuran pemilik."],"closure":"Identitas dipastikan atau barang dikembalikan dengan bukti; kendala diselesaikan."},{"id":"13","title":"Barang hendak diproses sebelum identitas jelas","operator":["Jangan mulai mesin atau menerima pembayaran untuk barang yang belum jelas pemiliknya.","Lengkapi identitas, pesanan, label, dan timbangan terlebih dahulu."],"owner":["Periksa percobaan yang ditolak dan lengkapi bukti yang kurang."],"evidence":["Riwayat tindakan, identitas, label, dan hasil timbangan."],"closure":"Pekerjaan baru dimulai setelah seluruh syarat terpenuhi."},{"id":"14","title":"Barang terlambat dicatat setelah tiba","operator":["Isi waktu barang benar-benar tiba.","Lengkapi foto, kantong, label, lokasi, dan alasan keterlambatan."],"owner":["Periksa keterlambatan lebih dari lima menit dan catat perbaikannya."],"evidence":["Waktu tiba, waktu pencatatan, foto, petugas, dan alasan."],"closure":"Penerimaan lengkap dan tindak lanjut keterlambatan sudah diperiksa."},{"id":"15","title":"Mesin dijalankan tanpa daftar pesanan","operator":["Hentikan pencatatan proses jika daftar cucian belum lengkap.","Cocokkan setiap label dengan pesanan sebelum mengisi kelompok cucian pada mesin."],"owner":["Periksa kejadian dan pastikan tidak ada barang yang diproses tanpa pesanan."],"evidence":["Nomor mesin, daftar pesanan, label, dan catatan petugas."],"closure":"Setiap cucian pada mesin dapat ditelusuri ke pesanan yang benar.","limit":"Pemeriksaan ini mengikuti catatan petugas. Mesin belum mengirim data otomatis ke aplikasi."},{"id":"16","title":"Pesanan hendak dihapus atau asalnya diubah","operator":["Gunakan pembatalan atau catatan kendala; jangan menghapus riwayat.","Jelaskan kesalahan dan bukti koreksi kepada Owner."],"owner":["Periksa koreksi; tandai tidak berlaku hanya bila tidak ada barang atau uang yang menggantung."],"evidence":["Pesanan awal, alasan, petugas, waktu, dan bukti koreksi."],"closure":"Riwayat asli tetap ada dan keputusan koreksi dapat ditelusuri."},{"id":"17","title":"Label barang hilang atau rusak","operator":["Tahan pekerjaan dan penyerahan sampai label dipastikan.","Ambil foto langsung dan pasang label pengganti yang sesuai pesanan."],"owner":["Periksa kecocokan pemilik dan barang jika ada keraguan."],"evidence":["Foto barang dan label pengganti, serta catatan pemeriksaan."],"closure":"Label benar sudah terpasang dan kendala terkait selesai."},{"id":"18","title":"Hasil timbang atau harga berubah sebelum dibayar","operator":["Buka Isi / koreksi timbangan dan perbarui setiap paket yang berubah.","Minta pelanggan menyetujui harga terbaru."],"owner":["Periksa alasan perubahan bila diperselisihkan."],"evidence":["Timbangan lama dan baru, foto, alasan, serta persetujuan terbaru."],"closure":"Harga terbaru disetujui; permintaan pembayaran lama tidak digunakan.","limit":"Koreksi setelah pembayaran atau pekerjaan dimulai memerlukan penanganan Owner; harga tidak dapat ditimpa begitu saja."},{"id":"19","title":"Pembayaran belum masuk atau kedaluwarsa","operator":["Periksa apakah dana benar-benar masuk.","Tandai permintaan yang kedaluwarsa dan buat permintaan baru bila belum dibayar."],"owner":["Cocokkan mutasi bank; jangan menyatakan lunas hanya dari gambar bukti."],"evidence":["Referensi pembayaran, mutasi bank, dan waktu pemeriksaan."],"closure":"Pembayaran sah dicatat satu kali; pesanan tetap tersimpan selama menunggu.","limit":"QRIS otomatis belum aktif. Cash dan Transfer tetap memerlukan bukti pemeriksaan."},{"id":"20","title":"Konfirmasi pembayaran otomatis datang dua kali","operator":["Jangan membuat penerimaan kedua untuk pembayaran yang sama.","Periksa nomor pesanan dan referensi pembayaran."],"owner":["Cocokkan dengan penyedia pembayaran; jika pelanggan benar-benar membayar dua kali, tangani kelebihan dana."],"evidence":["Referensi transaksi, jumlah yang masuk, dan catatan penyedia pembayaran."],"closure":"Satu pembayaran yang sama hanya dicatat satu kali.","limit":"Penyedia QRIS belum terhubung. Panduan ini belum berarti konfirmasi pembayaran otomatis sudah aktif."},{"id":"21","title":"Gambar bukti pembayaran belum dapat dipercaya","operator":["Ajukan bukti untuk diperiksa.","Jangan tandai lunas sebelum dana benar-benar diterima."],"owner":["Periksa mutasi rekening dari akun resmi dan isi referensi yang sesuai."],"evidence":["Bukti pelanggan, mutasi rekening, dan petugas pemeriksa."],"closure":"Lunas hanya setelah penerimaan dana dapat dibuktikan."},{"id":"22","title":"Petugas menerima pembayaran tunai","operator":["Hitung uang bersama pelanggan dan catat jumlah yang diterima.","Simpan bukti penerimaan, lalu ajukan setoran."],"owner":["Cocokkan setoran dengan penerimaan; pemeriksa harus berbeda dari penerima uang."],"evidence":["Bukti penerimaan, jumlah tunai, petugas, dan bukti setoran."],"closure":"Seluruh penerimaan tercatat dan setoran sudah cocok."},{"id":"23","title":"Petugas hendak menyetujui setorannya sendiri","operator":["Ajukan bukti setoran, lalu minta petugas lain yang berwenang memeriksa.","Jangan memakai akun bersama untuk penerimaan dan pemeriksaan."],"owner":["Pastikan pemeriksa bukan penerima uang atau pengaju setoran."],"evidence":["Nama penerima, pengaju, pemeriksa, serta bukti setoran."],"closure":"Setoran cocok setelah diperiksa oleh orang yang berbeda."},{"id":"24","title":"Jumlah setoran kurang","operator":["Hitung ulang penerimaan dan setoran bersama saksi.","Lengkapi kekurangan atau ajukan kembali angka yang benar beserta bukti."],"owner":["Periksa selisih, biaya, dan pengembalian dana; tetapkan petugas dan tenggat tindak lanjut."],"evidence":["Jumlah seharusnya, jumlah disetor, selisih, bukti, dan alasan."],"closure":"Setoran benar-benar cocok; kendala ditutup dengan bukti penyelesaian."},{"id":"25","title":"Pesanan dibatalkan setelah dibayar","operator":["Catat alasan pembatalan, posisi barang, dan uang yang sudah diterima.","Kembalikan barang dengan bukti; ajukan pengembalian dana sesuai keputusan Owner."],"owner":["Periksa dan setujui pengembalian dana.","Pastikan dana dikembalikan dari rekening yang benar dan dicocokkan oleh pemeriksa lain."],"evidence":["Pembayaran awal, keputusan Owner, bukti barang kembali, bukti dana keluar, dan rekening asal."],"closure":"Kewajiban barang dan dana sudah selesai; pembayaran awal tetap tercatat.","limit":"Form saat ini mendukung pengembalian penuh, termasuk pengembalian bertahap. Potongan biaya atau penolakan memerlukan keputusan Owner berbukti dan tetap dicatat sebagai kendala sampai tuntas."},{"id":"26","title":"Pesan WhatsApp tidak terkirim","operator":["Pantau pesanan dari Meja Laundry.","Hubungi pelanggan secara manual dan catat hasilnya."],"owner":["Periksa pesanan yang belum mendapat kabar dan tindak lanjuti keterlambatan."],"evidence":["Catatan upaya komunikasi, hasil kontak, dan petugas."],"closure":"Pesanan tetap berjalan sesuai syarat; pelanggan mendapat informasi melalui jalur yang tersedia.","limit":"WhatsApp otomatis belum terhubung. Tombol tindak lanjut mencatat kebutuhan komunikasi, belum mengirim pesan."},{"id":"27","title":"Barang hendak diserahkan tanpa bukti","operator":["Pastikan nama penerima dan siapkan bukti serah terima.","Simpan bukti sebelum menandai barang sudah diserahkan."],"owner":["Periksa pembayaran atau izin bayar nanti; tindak lanjuti bila bukti belum lengkap."],"evidence":["Nama penerima, bukti serah terima, petugas, waktu, dan pembayaran."],"closure":"Barang selesai diserahkan setelah bukti lengkap; penyelesaian dana tetap diperiksa terpisah."},{"id":"28","title":"Tamu akan segera keluar dari penginapan","operator":["Periksa waktu tamu akan keluar dan prioritaskan pekerjaan.","Hubungi pelanggan untuk menentukan waktu dan cara penyerahan."],"owner":["Tetapkan penanggung jawab dan keputusan bila cucian berisiko terlambat."],"evidence":["Waktu keluar, target selesai, hasil komunikasi, dan bukti penyerahan."],"closure":"Barang diserahkan atau penanganan alternatif disepakati dan dibuktikan.","limit":"Peringatan tampil saat waktu keluar kurang dari 24 jam. Penjadwalan dan pengiriman pengingat otomatis belum tersedia."}];if(typeof module!=="undefined"&&module.exports)module.exports=scenarios;else root.THLaundryScenarios=scenarios;})(typeof window!=="undefined"?window:globalThis);
